package com.familos.homepulse;

import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.net.URI;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.net.ssl.HttpsURLConnection;

/** HTTPS-only bridge. Durable batch identities survive retries and process death. */
public final class WellnessClient {
    public interface Listener { void onState(JSONObject state); void onStatus(String status); void onSync(); }
    private final Store store;
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ScheduledExecutorService network=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"HomePulse.network");t.setDaemon(true);return t;});
    private final AtomicBoolean syncing=new AtomicBoolean(false),refreshing=new AtomicBoolean(false),retryQueued=new AtomicBoolean(false);
    private volatile Listener listener;
    private volatile JSONObject protectedCredentials;
    private volatile String lastStatus="Archivio offline pronto",selectedAnalysis="";
    private int failures=0;

    public WellnessClient(Context context,Store store) { this.store=store;try{protectedCredentials=store.getSecret("bridge");}catch(RuntimeException error){lastStatus="Credenziali protette non disponibili; archivio offline conservato";} }
    public void setListener(Listener value) { listener=value;publish();status(lastStatus); }
    public boolean hasCredentials() { return protectedCredentials!=null; }
    public JSONObject credentials() { JSONObject value=protectedCredentials;return value==null?null:Store.copy(value); }
    public String baseUrl() { JSONObject value=protectedCredentials;return value==null?null:value.optString("server",null); }
    public String logicalRing() { String value=store.getJson("logicalRing",new JSONObject()).optString("id","");return value.isEmpty()?null:value; }
    public byte[] ownerKey() { String ring=logicalRing();if(ring==null)return null;try{JSONObject secret=store.getSecret("ring."+ring);if(secret==null)return null;byte[] key=Store.unhex(secret.optString("hex",""));return key.length==16?key:null;}catch(RuntimeException error){status("Chiave ring protetta non disponibile; nessuna sostituzione automatica");return null;} }
    public JSONObject state() { JSONObject result=store.getJson("bootstrap",new JSONObject());try{result.put("settings",store.settings());result.put("analysis",store.getJson(analysisKey(selectedAnalysis),new JSONObject()));result.put("sessions",store.sessions());JSONObject current=store.currentSession();result.put("active_session",current==null?JSONObject.NULL:current);String owner=store.getJson("owner",new JSONObject()).optString("name","");if(!owner.isEmpty())result.put("owner_name",owner);return Store.redacted(result);}catch(JSONException e){throw Store.failure(e);} }
    private void publish() { JSONObject snapshot=state();main.post(()->{Listener value=listener;if(value!=null)value.onState(snapshot);}); }
    private void status(String message) { lastStatus=message;main.post(()->{Listener value=listener;if(value!=null)value.onStatus(message);}); }
    private void changed() { main.post(()->{Listener value=listener;if(value!=null)value.onSync();});publish(); }
    public static String normalizeBase(String input) { try{URI value=new URI(input==null?"":input.trim());String path=value.getPath();if(!"https".equalsIgnoreCase(value.getScheme())||value.getHost()==null||value.getRawUserInfo()!=null||value.getRawQuery()!=null||value.getRawFragment()!=null)throw new IllegalArgumentException();if(path==null||path.isEmpty()||path.equals("/"))path="/api/wellness/v1";while(path.endsWith("/"))path=path.substring(0,path.length()-1);if(!path.equals("/api/wellness/v1"))throw new IllegalArgumentException();return new URI("https",null,value.getHost(),value.getPort(),path,null,null).toASCIIString();}catch(Exception error){throw new IllegalArgumentException("Serve il server FamilOS HTTPS, senza credenziali o parametri nell’indirizzo");} }
    private JSONObject request(String endpoint,String method,JSONObject body,String base,JSONObject credential)throws Exception { String url=normalizeBase(base)+"/"+endpoint;HttpsURLConnection connection=(HttpsURLConnection)new URI(url).toURL().openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(25000);connection.setRequestMethod(method);connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("Content-Type","application/json");if(credential!=null)connection.setRequestProperty("Authorization","Bearer "+credential.getString("access_token"));try{if(body!=null){byte[] bytes=body.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>5_000_000)throw new IllegalArgumentException("Batch oltre il limite di rete");connection.setDoOutput(true);connection.setFixedLengthStreamingMode(bytes.length);try(java.io.OutputStream output=connection.getOutputStream()){output.write(bytes);}}int code=connection.getResponseCode();if(code<200||code>=300)throw new java.io.IOException(code==401||code==403?"Associazione da verificare":"Server non disponibile");try(InputStream input=connection.getInputStream();ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(output.size()+count>10_000_000)throw new java.io.IOException("Risposta oltre il limite");output.write(buffer,0,count);}return new JSONObject(output.toString(StandardCharsets.UTF_8.name()));}}finally{connection.disconnect();} }
    private JSONObject request(String path,String method,JSONObject body)throws Exception { JSONObject credentials=credentials();if(credentials==null)throw new IllegalStateException("Associa prima FamilOS");return request(path,method,body,credentials.getString("server"),credentials); }
    public void enroll(String server,String code,String deviceName) { final String base;try{base=normalizeBase(server);if(code==null||code.trim().isEmpty()||code.length()>128)throw new IllegalArgumentException("Codice di associazione non valido");}catch(RuntimeException error){status(error.getMessage());return;}network.execute(()->{try{JSONObject response=request("bridges/enroll","POST",Store.object("pairing_code",code.trim(),"device_name",deviceName==null||deviceName.trim().isEmpty()?"Home Pulse · Android":deviceName.trim().substring(0,Math.min(120,deviceName.trim().length()))),base,null);String token=response.getString("access_token"),device=response.getString("device_id");if(token.isEmpty()||token.length()>300||device.isEmpty())throw new IllegalArgumentException();JSONObject value=Store.object("server",base,"device_id",device,"access_token",token);store.setSecret("bridge",value);protectedCredentials=value;applyBootstrap(response);status("FamilOS associato; dati protetti salvati");refresh();sync();}catch(Exception error){status("Associazione non completata. Verifica server e codice; archivio offline conservato");}}); }
    public void saveSettings(JSONObject value) { JSONObject snapshot=Store.redacted(Store.copy(value));Workout.validateSettings(snapshot);synchronized(store){store.saveSettings(snapshot);store.setJson("settings.sync",Store.object("dirty",true,"revision",UUID.randomUUID().toString()));}publish();status("Impostazioni salvate sul telefono");refresh(); }
    private void pushSettings()throws Exception { JSONObject snapshot;String revision;synchronized(store){snapshot=store.settings();revision=store.getJson("settings.sync",new JSONObject()).optString("revision","");}JSONObject response=request("mobile/settings","PATCH",snapshot);synchronized(store){JSONObject state=store.getJson("settings.sync",new JSONObject());if(revision.equals(state.optString("revision")))store.setJson("settings.sync",Store.object("dirty",false,"revision",revision));}applyBootstrap(response); }
    private void applyBootstrap(JSONObject response) { JSONObject binding=response.optJSONObject("ring_binding");if(binding!=null){String id=binding.optString("logical_ring_id","");if(!id.isEmpty()){String hex=binding.optString("owner_key_hex","");if(!hex.isEmpty()){byte[] key=Store.unhex(hex);if(key.length!=16)throw new IllegalArgumentException("Chiave ring non valida");store.setSecret("ring."+id,Store.object("hex",Store.hex(key)));}store.setJson("logicalRing",Store.object("id",id));}}else if(response.has("ring_binding")&&response.isNull("ring_binding"))store.setJson("logicalRing",null);
        String owner=response.optString("owner_name","");if(!owner.isEmpty())store.setJson("owner",Store.object("name",owner));JSONObject remoteSettings=response.optJSONObject("settings");synchronized(store){if(remoteSettings!=null&&!store.getJson("settings.sync",new JSONObject()).optBoolean("dirty",false)){Workout.validateSettings(remoteSettings);store.saveSettings(remoteSettings);}if(store.pendingWorkoutCount()==0&&response.has("sessions")){JSONArray sessions=response.optJSONArray("sessions"),decoded=new JSONArray();if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject value=decodeSession(sessions.optJSONObject(i));if(value!=null)decoded.put(value);}store.reconcileSessions(decoded,decodeSession(response.optJSONObject("active_session")));}}
        JSONObject safe=Store.redacted(response);safe.remove("device_id");store.setJson("bootstrap",safe);publish(); }
    private static JSONObject decodeSession(JSONObject input) { if(input==null)return null;String id=input.optString("id",""),status=input.optString("status","");if(id.isEmpty()||!java.util.Arrays.asList("active","paused","completed","rejected","ended","false_detection").contains(status))return null;double started=input.optDouble("started_at",Double.NaN),elapsed=input.optDouble("active_seconds",Double.NaN);if(!Double.isFinite(started)||!Double.isFinite(elapsed)||started<0||elapsed<0||input.optJSONObject("config")==null||input.optJSONObject("profile")==null)return null;try{Workout.validateSettings(Store.object("config",input.getJSONObject("config"),"profile",input.getJSONObject("profile")));JSONObject result=Store.copy(input);result.put("remote_id",id);result.put("status",status.equals("ended")?"completed":status.equals("false_detection")?"rejected":status);result.put("state",status.equals("active")?"running":status.equals("completed")||status.equals("ended")?"ended":status.equals("rejected")||status.equals("false_detection")?"false_detection":status);if(status.equals("active")){result.put("running_since",System.currentTimeMillis()/1000.0);result.put("running_elapsed_ms",android.os.SystemClock.elapsedRealtime());result.put("boot_epoch_ms",System.currentTimeMillis()-android.os.SystemClock.elapsedRealtime());}else result.put("running_since",JSONObject.NULL);return result;}catch(Exception error){return null;} }
    public void refresh() { if(!hasCredentials()){publish();return;}if(!refreshing.compareAndSet(false,true))return;network.execute(()->{try{if(store.getJson("settings.sync",new JSONObject()).optBoolean("dirty",false))pushSettings();else applyBootstrap(request("mobile/bootstrap","GET",null));JSONObject analysis=request("mobile/analysis","GET",null);store.setJson(analysisKey(""),analysis);failures=0;status("Dati FamilOS aggiornati");publish();sync();}catch(Exception error){status("Offline · impostazioni e allenamenti conservati");retry();}finally{refreshing.set(false);}}); }
    public void sync() { if(!hasCredentials()||!syncing.compareAndSet(false,true))return;network.execute(()->{boolean remaining=false;try{for(int pass=0;pass<12;pass++){JSONObject batch=store.prepareBatch(500);if(batch==null){status("Sincronizzato");break;}JSONObject answer=request("bridges/events","POST",batch);String id=batch.getString("batch_id");if(!id.equals(answer.optString("batch_id")))throw new IllegalArgumentException("Conferma batch non valida");JSONArray values=answer.getJSONArray("accepted_event_ids");Set<String> accepted=new HashSet<>();for(int i=0;i<values.length();i++){Object item=values.get(i);if(!(item instanceof String))throw new IllegalArgumentException("Conferma eventi non valida");accepted.add((String)item);}store.acknowledge(id,accepted);failures=0;changed();if(accepted.isEmpty()){remaining=false;retry();break;}remaining=store.pendingCount()>0;if(!remaining){status("Sincronizzazione confermata");break;}}}catch(Exception error){remaining=false;status("Invio rinviato: coda locale intatta");retry();}finally{syncing.set(false);if(remaining)network.schedule(this::sync,250,TimeUnit.MILLISECONDS);}}); }
    private void retry() { if(!retryQueued.compareAndSet(false,true))return;long delay=Math.min(300,3L<<Math.min(6,failures++));network.schedule(()->{retryQueued.set(false);refresh();sync();},delay,TimeUnit.SECONDS); }
    private static String analysisKey(String session) { return session==null||session.isEmpty()?"analysis.last24h":"analysis."+session; }
    public void loadAnalysis(String sessionId) { selectedAnalysis=sessionId==null?"":sessionId;publish();final String selection=selectedAnalysis;analysis(selection,value->{if(selection.equals(selectedAnalysis))publish();}); }
    public void analysis(String sessionId,Consumer<JSONObject> callback) { final String session=sessionId==null?"":sessionId;JSONObject cached=store.getJson(analysisKey(session),new JSONObject());main.post(()->callback.accept(cached));if(!hasCredentials())return;network.execute(()->{try{String path="mobile/analysis"+(session.isEmpty()?"":"?session_id="+URLEncoder.encode(session,StandardCharsets.UTF_8.name()));JSONObject response=request(path,"GET",null);store.setJson(analysisKey(session),response);main.post(()->callback.accept(Store.copy(response)));}catch(Exception error){status("Analisi offline: ultima copia disponibile");}}); }
}
